		if (this.inMemBatter['AtBat_Mystery_CaptainStarSwing'] === 0) {
			if (this.inMemBatter['nonCaptainStarSwingContact'] !== 0) {
				charged = 0.0;
				// NonCaptainStarSwing array
				contactArray =
					STAR_SWING_EXIT_VELOCITY_ARRAY[this.inMemBatter['nonCaptainStarSwingContact'] - 1][niceSour];
			}
		} else {
			charged = 0.0;
			// CaptainStarSwingArray
			contactArray =
				CAPTAIN_STAR_SWING_EXIT_VELOCITY_ARRAY[this.inMemBatter['AtBat_Mystery_CaptainStarSwing'] - 1][
					niceSour
				];
		}

		if (this.inMemBatter['AtBat_Mystery_DidPopFlyOrGrounderConnect'] !== false) {
			this.inMemBatter['BatterAtPlate_BatterCharge_Down'] = 1.0;
		}

